import{_ as t,o as a,c as s,ag as i}from"./chunks/framework.B7PviQjB.js";const o="/docs/images/developers/self-hosting/local-login.png",u=JSON.parse('{"title":"Local development","description":"Start the full Wafflebase stack on localhost with Docker Compose and the dev servers.","frontmatter":{"title":"Local development","description":"Start the full Wafflebase stack on localhost with Docker Compose and the dev servers.","type":"how-to"},"headers":[],"relativePath":"developers/self-hosting/local-development.md","filePath":"developers/self-hosting/local-development.md"}'),n={name:"developers/self-hosting/local-development.md"};function d(l,e,r,h,c,p){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="local-development" tabindex="-1">Local development <a class="header-anchor" href="#local-development" aria-label="Permalink to &quot;Local development&quot;">​</a></h1><p>Start the full Wafflebase stack on <code>localhost</code> with Docker Compose and three dev servers.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>Install Node.js 22, pnpm 10.5.2, and Docker with Compose v2. See <a href="/docs/developers/self-hosting/#requirements">Requirements</a>.</li><li>Create a GitHub OAuth app with the callback URL <code>http://localhost:3000/auth/github/callback</code>. See <a href="/docs/developers/self-hosting/sign-in.html#set-up-github-sign-in">Set up GitHub sign-in</a>.</li></ul></div><h2 id="clone-and-install" tabindex="-1">Clone and install <a class="header-anchor" href="#clone-and-install" aria-label="Permalink to &quot;Clone and install&quot;">​</a></h2><ol><li><p>Clone the repository and install dependencies:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/wafflebase/wafflebase.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wafflebase</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div></li><li><p>Build the shared core package, which the editors and the backend import from its build output:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>Run it again after you pull changes to <code>packages/core</code>.</p></li></ol><h2 id="start-the-infrastructure" tabindex="-1">Start the infrastructure <a class="header-anchor" href="#start-the-infrastructure" aria-label="Permalink to &quot;Start the infrastructure&quot;">​</a></h2><ol><li><p>Start the default services:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div></li></ol><table tabindex="0"><thead><tr><th>Service</th><th>Ports</th><th>Purpose</th></tr></thead><tbody><tr><td><code>postgres</code></td><td><code>5432</code></td><td>PostgreSQL 16 (user, password, and database are all <code>wafflebase</code>)</td></tr><tr><td><code>yorkie</code></td><td><code>8080</code>, <code>8081</code></td><td>Document sync (<code>8080</code> RPC, <code>8081</code> profiling)</td></tr><tr><td><code>minio</code></td><td><code>9000</code>, <code>9001</code></td><td>S3-compatible blob storage (<code>9000</code> API, <code>9001</code> console; <code>minioadmin</code> / <code>minioadmin</code>)</td></tr><tr><td><code>azurite</code></td><td><code>10000</code></td><td>Azure Blob emulator, used only by the lakehouse integration tests</td></tr></tbody></table><p>To skip the Azure emulator, start only what the app needs:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yorkie</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> minio</span></span></code></pre></div><p>The analytics services (<code>kafka</code>, <code>starrocks</code>) start only with <code>--profile analytics</code>. See <a href="/docs/developers/self-hosting/optional-features.html#turn-on-share-link-analytics">Turn on share-link analytics</a>.</p><h2 id="create-the-backend-configuration" tabindex="-1">Create the backend configuration <a class="header-anchor" href="#create-the-backend-configuration" aria-label="Permalink to &quot;Create the backend configuration&quot;">​</a></h2><ol><li><p>Create <code>packages/backend/.env</code> with the six required values:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DATABASE_URL=postgresql://wafflebase:wafflebase@localhost:5432/wafflebase</span></span>
<span class="line"><span>JWT_SECRET=change-me</span></span>
<span class="line"><span>GITHUB_CLIENT_ID=your_github_client_id</span></span>
<span class="line"><span>GITHUB_CLIENT_SECRET=your_github_client_secret</span></span>
<span class="line"><span>GITHUB_CALLBACK_URL=http://localhost:3000/auth/github/callback</span></span>
<span class="line"><span>FRONTEND_URL=http://localhost:5173</span></span></code></pre></div></li></ol><p>Outside production, blob storage falls back to the local MinIO container and Yorkie to <code>http://localhost:8080</code>, so you need nothing else to start. The frontend&#39;s committed <code>packages/frontend/.env</code> already points at <code>localhost</code>. Every other variable is in <a href="/docs/developers/self-hosting/configuration.html">Configuration</a>.</p><h2 id="create-the-database-schema" tabindex="-1">Create the database schema <a class="header-anchor" href="#create-the-database-schema" aria-label="Permalink to &quot;Create the database schema&quot;">​</a></h2><ol><li><p>Apply the migrations:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span></span></code></pre></div></li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>pnpm backend migrate</code> runs <code>prisma migrate dev</code>, which can generate migration files and offer to reset the database. Use it only on a development database. Production uses <code>prisma migrate deploy</code>; see <a href="/docs/developers/self-hosting/deploy.html#run-database-migrations">Run database migrations</a>.</p></div><h2 id="start-the-dev-servers" tabindex="-1">Start the dev servers <a class="header-anchor" href="#start-the-dev-servers" aria-label="Permalink to &quot;Start the dev servers&quot;">​</a></h2><ol><li><p>Start everything:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div></li><li><p>Open <code>http://localhost:5173</code> and click <strong>Continue with GitHub</strong>.</p></li></ol><table tabindex="0"><thead><tr><th>Server</th><th>Port</th><th>Run on its own</th></tr></thead><tbody><tr><td>Frontend (Vite)</td><td><code>5173</code></td><td><code>pnpm frontend dev</code></td></tr><tr><td>Backend (NestJS, watch mode)</td><td><code>3000</code></td><td><code>pnpm backend start:dev</code></td></tr><tr><td>Documentation (VitePress)</td><td><code>5174</code></td><td><code>pnpm documentation dev</code></td></tr></tbody></table><p>The frontend proxies <code>/docs</code> to the documentation server, so the in-app help links work only while it runs. Signing in for the first time creates your account and your first workspace.</p><p><img src="`+o+'" alt="Wafflebase sign-in page served from localhost:5173 with the Continue with GitHub button"></p><h2 id="run-the-tests" tabindex="-1">Run the tests <a class="header-anchor" href="#run-the-tests" aria-label="Permalink to &quot;Run the tests&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it runs</th></tr></thead><tbody><tr><td><code>pnpm verify:fast</code></td><td>Lint and unit tests</td></tr><tr><td><code>pnpm test</code></td><td>Unit tests across all packages</td></tr><tr><td><code>pnpm backend test:e2e</code></td><td>Backend end-to-end tests. Database-backed suites need <code>RUN_DB_INTEGRATION_TESTS=true</code>, and Yorkie-attached ones <code>RUN_YORKIE_INTEGRATION_TESTS=true</code></td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/developers/self-hosting/configuration.html">Configuration</a> for every backend and frontend variable.</li><li><a href="/docs/developers/self-hosting/sign-in.html">Sign-in providers</a> to add Google sign-in.</li><li><a href="/docs/developers/self-hosting/troubleshooting.html">Troubleshooting</a> if the backend does not start.</li><li><a href="https://github.com/wafflebase/wafflebase/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer"><code>CONTRIBUTING.md</code></a> for the development workflow.</li></ul>',26)])])}const b=t(n,[["render",d]]);export{u as __pageData,b as default};
